// Runtime mode: on device always true, in editor false by default (set during play mode)
namespace Deki
{

#ifdef DEKI_EDITOR
bool Engine::s_RuntimeMode = false;
#else
bool Engine::s_RuntimeMode = true;
#endif

bool Engine::IsRuntimeMode()
{
    return s_RuntimeMode;
}
void Engine::SetRuntimeMode(bool runtime)
{
    s_RuntimeMode = runtime;
}

// Engine implementation
Engine::Engine()
    : m_Initialized(false),
      m_IsDirty(true)  // Start dirty to ensure initial render
      ,
      m_SceneSystem(new SceneSystem()),
      m_LifecycleManager(new LifecycleManager()),
      m_Renderer(nullptr)  // Set by rendering package via SetRenderSystem()
      ,
      m_InputSystem(nullptr)  // Set by input package via SetInputSystem()
      ,
      m_TargetFps(30),
      m_Running(false)
{
}

Engine::~Engine()
{
    Shutdown();
    // Note: renderer is owned by the rendering package, not by Engine
    delete m_LifecycleManager;
    delete m_SceneSystem;
}

Engine& Engine::GetInstance()
{
    static Engine s_Instance;
    return s_Instance;
}

// Global settings accessor (works without engine initialization)
EngineSettings& EngineSettings::Global()
{
    static EngineSettings s_GlobalSettings;
    return s_GlobalSettings;
}

EngineHost EngineHost::Device()
{
    return EngineHost{};
}

EngineHost EngineHost::Editor()
{
    EngineHost host;
    host.initializeProviders = false;  // EditorProjectManager installs memory, filesystem and time
    host.pollInput = false;            // the editor feeds input from its own event loop
    host.tickPower = false;
    host.renderAndPresent = false;  // play mode calls Render() and presents through EditorDisplay
    host.logFrameStats = false;
    host.ownsMainLoop = false;  // the editor has its own frame loop
    return host;
}

bool Engine::Initialize()
{
#ifdef DEKI_EDITOR
    return Initialize(EngineHost::Editor());
#else
    return Initialize(EngineHost::Device());
#endif
}

bool Engine::Initialize(const EngineHost& host)
{
    Engine& engine = GetInstance();
    if (engine.m_Initialized)
    {
        return true;
    }
    engine.m_Host = host;

    // Register all engine components before any scene loading. Static
    // initializers are unreliable on some platforms, so this is explicit; the
    // list is generated by the reflection codegen.
    DekiRegisterAllComponents();
#ifndef DEKI_EDITOR
    DekiRegisterProjectPackages();  // firmware builds: statically linked packages
#endif

    LogSystem::Initialize();
    Time::Initialize();

    bool settingsLoaded = false;
    if (host.initializeProviders)
    {
        if (!FileSystem::Initialize())
        {
            DEKI_LOG_ERROR("Failed to initialize DekiFileSystem");
            return false;
        }
        // Load project settings from storage
        settingsLoaded = ProjectSettings::LoadFromFile();
        if (settingsLoaded)
        {
            DEKI_LOG_INTERNAL("Project settings loaded successfully");
            int32_t fps = ProjectSettings::GetTargetFPS();
            DEKI_LOG_INTERNAL("ProjectSettings targetFPS=%d", fps);
            if (fps > 0)
            {
                engine.SetTargetFPS(fps);
            }
            engine.SetScreenDiagonalInches(ProjectSettings::GetScreenDiagonalInches());
        }
        else
        {
            DEKI_LOG_INTERNAL("No project settings found, using defaults");
        }
    }

    // Package systems (render system, passes, ...). On device this reads the
    // pipeline configuration from ProjectSettings; in the editor the DLL entry
    // points may also call these (idempotent).
    DekiInitPackageSystems();

    if (host.initializeProviders && !Memory::Initialize())
    {
        DEKI_LOG_ERROR("Failed to initialize DekiMemory");
        return false;
    }

    // Assets kept in internal storage are there from the start. On external
    // storage, the package that mounts it (deki-sdcard) loads them once the
    // card is up.
    if (settingsLoaded && ProjectSettings::GetAssetStorage() == Storage::Internal &&
        !AssetManager::Get()->LoadAssetRoot(Storage::AssetRoot(Storage::Internal)))
    {
        DEKI_LOG_ERROR("This build keeps its assets in internal storage, and they are not there");
        return false;
    }

    // Display and input backends are installed by SetupComponents in the boot
    // scene on device, and by play mode in the editor.

    // The framebuffer's size and format come from the display, which a
    // boot-scene SetupComponent (device) or play mode (editor) installs after
    // this. SetDisplay allocates it then.

    // Setup the scene system
    if (!engine.m_SceneSystem->Setup())
    {
        DEKI_LOG_ERROR("Failed to setup SceneSystem");
        if (engine.m_Display)
        {
            engine.m_Display->Shutdown();
        }
        return false;
    }

    engine.m_Initialized = true;
    // A display installed before initialization (a host that sets it up first)
    // is sized now that the render system exists.
    if (engine.m_Display && engine.m_Renderer)
    {
        engine.SizeFramebufferToDisplay();
    }
    DEKI_LOG_INTERNAL("DekiEngine initialized (%s%s)", host.ownsMainLoop ? "device" : "hosted",
                      engine.m_Renderer ? "" : ", headless");
    return true;
}

void Engine::Shutdown()
{
    if (!m_Initialized)
    {
        return;
    }

    if (m_SceneSystem)
    {
        m_SceneSystem->SetRootScene(nullptr);
    }

    DekiShutdownPackageSystems();
    if (m_InputSystem)
    {
        m_InputSystem->Shutdown();
    }
    if (m_Display)
    {
        m_Display->Shutdown();
        m_Display = nullptr;
        m_DisplayName.clear();
    }
    FileSystem::Shutdown();
    // Last: the backends above may still free through it.
    Memory::Shutdown();
    m_Initialized = false;
}

void Engine::Update(uint32_t deltaTime)
{
    if (!m_Initialized)
    {
        if (m_Host.ownsMainLoop)
        {
            DEKI_LOG_ERROR("DekiEngine::Update() called but engine not initialized!");
        }
        return;
    }

    m_FpsCounter.BeginFrame();

    // Poll and dispatch input first, so this frame's logic sees it.
    if (m_Host.pollInput && m_InputSystem)
    {
        m_InputSystem->Update();
    }

    // Power management. Tick() may block here on real light sleep until the
    // wake source fires; on platforms without HW sleep it sets state directly.
    // After Tick() returns, skip the rest of the frame if still Sleeping (soft
    // sleep on platforms whose Tick doesn't block).
    if (m_Host.tickPower)
    {
        if (auto* power = Power::GetCurrent())
        {
            power->Tick();
            if (power->GetState() == IPower::State::Sleeping)
            {
                m_FpsCounter.EndFrame();
                return;
            }
        }
    }

    if (!m_SceneSystem || !m_SceneSystem->HasRootScene())
    {
        static bool s_LoggedNoScene = false;
        if (!s_LoggedNoScene)
        {
            DEKI_LOG_WARNING("DekiEngine: No active scene");
            s_LoggedNoScene = true;
        }
        // Lifecycle and Render() are no-ops without a scene; the callbacks
        // still run and the display still presents.
    }

    Time::Update(deltaTime);
    const uint32_t t0 = Time::GetTime();

    // Behaviour lifecycle (Awake, Start, Update) with scene change detection
    ProcessLifecycle();
    Scene* started = m_SceneSystem ? m_SceneSystem->GetRootScene() : nullptr;

    if (m_GameUpdateCallback)
    {
        m_GameUpdateCallback();
    }

    for (const auto& callback : m_UpdateCallbacks)
    {
        if (callback)
        {
            callback(deltaTime);
            m_IsDirty = true;  // assume callbacks change something
        }
    }
    StartRootSceneSetSince(started);

    const uint32_t t1 = Time::GetTime();
    uint32_t t2 = t1;
    uint32_t t3 = t1;

    if (m_Host.renderAndPresent)
    {
        Render();
        t2 = Time::GetTime();

        PresentFrame();
        t3 = Time::GetTime();
    }

    m_FpsCounter.EndFrame();
    m_LastFrameTimings = FrameTimings{ t1 - t0, t2 - t1, t3 - t2 };

    if (m_Host.logFrameStats)
    {
        // Every 120 frames, to keep the log readable
        uint32_t totalFrames = m_FpsCounter.GetTotalFrames();
        if (totalFrames % 120 == 0)
        {
            int fpsInt = (int)m_FpsCounter.GetFPS();
            int fpsFrac = (int)((m_FpsCounter.GetFPS() - fpsInt) * 100);
            int minFpsInt = (int)m_FpsCounter.GetMinFPS();
            int maxFpsInt = (int)m_FpsCounter.GetMaxFPS();
            int frameTimeInt = (int)m_FpsCounter.GetAverageFrameTime();

            DEKI_LOG_INTERNAL(
                "Frame %u - FPS: %d.%02d (min: %d, max: %d, time: %d ms) | update: %u render: %u present: %u",
                totalFrames, fpsInt, fpsFrac, minFpsInt, maxFpsInt, frameTimeInt, (unsigned)(t1 - t0),
                (unsigned)(t2 - t1), (unsigned)(t3 - t2));
        }
    }
}

void Engine::Render()
{
    if (!m_Initialized || !m_Renderer || !m_SceneSystem || !m_SceneSystem->HasRootScene())
    {
        return;
    }
    if (m_Renderer->GetScreenWidth() <= 0 || m_Renderer->GetScreenHeight() <= 0)
    {
        // Without a display there is no size to render at, and the engine never
        // guesses one. The first frames run before the boot scene's setup has
        // installed the display, so this is only said once it is overdue.
        if (!m_NoFramebufferLogged && ++m_FramesWithoutFramebuffer == kFramesBeforeNoDisplayError)
        {
            DEKI_LOG_ERROR("Nothing is rendered: no display has given the framebuffer a size. "
                           "The target's boot scene must set up a display.");
            m_NoFramebufferLogged = true;
        }
        return;
    }
    m_Renderer->Render(m_SceneSystem->GetRootScene());
}

void Engine::PresentFrame()
{
    if (!m_Display || !m_Renderer)
    {
        return;
    }

    const uint8_t* fb = m_Renderer->GetFrameBuffer();
    const int32_t w = m_Renderer->GetScreenWidth();
    const int32_t h = m_Renderer->GetScreenHeight();
    const ColorFormat format = m_Renderer->GetColorFormat();

    int32_t count = -1;
    const Rect* rects = m_Renderer->GetPresentRects(&count);
    if (count < 0 || !m_Display->SupportsPartialPresent())
    {
        m_Display->Present(fb, w, h, format);
        return;
    }
    m_Display->PresentRegions(fb, w, h, format, rects, count);
}

void Engine::RequestFullRefresh()
{
    if (m_Renderer)
    {
        m_Renderer->MarkAllDirty();
    }
    if (m_Display)
    {
        m_Display->RequestFullRefresh();
    }
}

void Engine::RunMainLoop()
{
    if (!m_Host.ownsMainLoop)
    {
        DEKI_LOG_WARNING("DekiEngine::RunMainLoop: the host drives the frame loop");
        return;
    }
    if (!m_Initialized)
    {
        DEKI_LOG_WARNING("GameEngine not m_Initialized, cannot run main loop");
        return;
    }

    m_Running = true;
    // A frame's budget in microseconds (16667 at 60 fps). The deadline moves
    // on by it each frame, carrying the part of a millisecond, so frames
    // average the target rate although the clock and Delay count whole
    // milliseconds: 1000 / 60 as a whole number of milliseconds ran at 62.5.
    const uint32_t frameUs = 1000000u / static_cast<uint32_t>(m_TargetFps);
    uint32_t lastTime = Time::GetTime();
    uint32_t deadline = lastTime;  // milliseconds
    uint32_t deadlineUs = 0;       // and the microseconds past it
    // The longest the loop runs without blocking. Far inside the task
    // watchdog's timeout (seconds), and rare enough to cost little.
    constexpr uint32_t kMaxMsWithoutYield = 100;
    uint32_t lastYield = lastTime;

    DEKI_LOG_INTERNAL("RunMainLoop starting with target FPS: %d", m_TargetFps);

    while (m_Running)
    {
        // Check if application should exit (e.g., window close)
        if (m_InputSystem && m_InputSystem->ShouldExit())
        {
            m_Running = false;
            break;
        }

        uint32_t currentTime = Time::GetTime();
        uint32_t elapsed = currentTime - lastTime;

        if (elapsed == 0)
        {
            elapsed = 1;
        }

        // Update (includes Render + Present; m_GameUpdateCallback runs inside)
        Update(elapsed);

        m_IsDirty = false;  // Clear dirty flag after rendering

        // Frame rate limiting: wait for the frame's deadline. A frame more
        // than a budget late sets the next one from now instead of running
        // the next frames back to back to catch up.
        deadlineUs += frameUs;
        deadline += deadlineUs / 1000u;
        deadlineUs %= 1000u;
        const uint32_t now = Time::GetTime();
        const int32_t left = static_cast<int32_t>(deadline - now);
        if (left < -static_cast<int32_t>(frameUs / 1000u))
        {
            deadline = now;
            deadlineUs = 0;
        }
        if (left > 0)
        {
            Time::Delay(static_cast<uint32_t>(left));
            lastYield = now;
        }
        else if (now - lastYield >= kMaxMsWithoutYield)
        {
            // A frame that overran its budget starts the next one at once, but
            // the loop still blocks for a tick now and then, so the idle task
            // runs (it feeds the task watchdog) and so do tasks below this one.
            // Yielding after every late frame instead cost a slow scene a
            // millisecond a frame.
            Time::Delay(1);
            lastYield = Time::GetTime();
        }

        lastTime = currentTime;
    }

    m_Running = false;
    DEKI_LOG_INTERNAL("RunMainLoop ended");
}

void Engine::StopMainLoop()
{
    m_Running = false;
}

void Engine::ProcessLifecycle()
{
    if (!m_SceneSystem)
    {
        return;
    }

    // Flush deferred scene deletions from previous frame.
    // Safe: no behaviour code is executing at this point.
    m_SceneSystem->FlushPendingDeletions();

    if (!m_SceneSystem->HasRootScene())
    {
        return;
    }

    Scene* activeScene = m_SceneSystem->GetRootScene();

    // Process behaviour lifecycle
    uint32_t t0 = Time::GetTime();
    m_LifecycleManager->ProcessInternalAwake(activeScene);
    uint32_t t1 = Time::GetTime();
    m_LifecycleManager->ProcessAwake(activeScene);
    uint32_t t2 = Time::GetTime();
    m_LifecycleManager->ProcessStart(activeScene);
    uint32_t t3 = Time::GetTime();
    uint32_t total = t3 - t0;
    if (total > 5)
    {
        DEKI_LOG_INTERNAL("[PERF] ProcessLifecycle: InternalAwake=%ums, Awake=%ums, Start=%ums, total=%ums", t1 - t0,
                          t2 - t1, t3 - t2, total);
    }

    // Check if scene changed during Start (e.g., SetRootScene called)
    // IMPORTANT: If changed, the old scene may have been deleted!
    // Do NOT use activeScene after this point if it changed.
    // RuntimeUpdate() (component physics: roller/scroll momentum + snap, etc.)
    // takes a per-frame delta in SECONDS. Time stores it in milliseconds.
    const float runtimeDeltaSeconds = Time::GetDeltaTimeF() / 1000.0f;

    Scene* currentScene = m_SceneSystem->GetRootScene();
    if (currentScene != activeScene)
    {
        // Scene was replaced during Start - process lifecycle on new scene
        if (currentScene != nullptr)
        {
            DEKI_LOG_INTERNAL("ProcessLifecycle: Scene changed during Start! newScene=%p, objects=%zu",
                              (void*)currentScene, currentScene->GetObjects().size());
            m_LifecycleManager->ProcessInternalAwake(currentScene);
            m_LifecycleManager->ProcessAwake(currentScene);
            m_LifecycleManager->ProcessStart(currentScene);
            // Update on the NEW scene (script Update() then component RuntimeUpdate())
            m_LifecycleManager->ProcessUpdate(currentScene);
            m_LifecycleManager->ProcessRuntimeUpdate(currentScene, runtimeDeltaSeconds);
        }
    }
    else
    {
        // Scene didn't change - safe to call Update on activeScene
        m_LifecycleManager->ProcessUpdate(activeScene);
        m_LifecycleManager->ProcessRuntimeUpdate(activeScene, runtimeDeltaSeconds);
        // A button that opens a scene does it here, in Update.
        StartRootSceneSetSince(activeScene);
    }

    // Update scene system
    m_SceneSystem->Update(0);  // deltaTime not used currently
}

void Engine::StartRootSceneSetSince(Scene* started)
{
    Scene* scene = m_SceneSystem ? m_SceneSystem->GetRootScene() : nullptr;
    if (!scene || scene == started)
    {
        return;
    }
    // The scene it replaced goes first: nothing of it runs any more, and both
    // at once may not fit in a small board's memory.
    m_SceneSystem->FlushPendingDeletions();
    m_LifecycleManager->ProcessInternalAwake(scene);
    m_LifecycleManager->ProcessAwake(scene);
    m_LifecycleManager->ProcessStart(scene);
}

void Engine::SetRootScene(Scene* scene, bool takeOwnership)
{
    if (m_SceneSystem)
    {
        m_SceneSystem->SetRootScene(scene, takeOwnership);
    }
}

Scene* Engine::GetRootScene() const
{
    return m_SceneSystem ? m_SceneSystem->GetRootScene() : nullptr;
}

Scene* Engine::CreateScene()
{
    return m_SceneSystem ? m_SceneSystem->CreateScene() : nullptr;
}

size_t Engine::RegisterUpdate(const UpdateCallback& callback)
{
    if (!callback)
    {
        return SIZE_MAX;
    }
    // Reuse a freed slot so ids stay stable for the live callbacks.
    for (size_t i = 0; i < m_UpdateCallbacks.size(); ++i)
    {
        if (!m_UpdateCallbacks[i])
        {
            m_UpdateCallbacks[i] = callback;
            return i;
        }
    }
    m_UpdateCallbacks.push_back(callback);
    return m_UpdateCallbacks.size() - 1;
}

void Engine::UnregisterUpdate(size_t id)
{
    // Slots are nulled rather than erased: ids are indices, and the update
    // loop already skips empty entries.
    if (id < m_UpdateCallbacks.size())
    {
        m_UpdateCallbacks[id] = nullptr;
    }
}

void Engine::RunUpdateCallbacks(uint32_t deltaTime)
{
    for (const auto& callback : m_UpdateCallbacks)
    {
        if (callback)
        {
            callback(deltaTime);
        }
    }
}

void Engine::SetGameUpdateCallback(const GameUpdateCallback& callback)
{
    m_GameUpdateCallback = callback;
}

void Engine::SetTargetFPS(uint32_t fps)
{
    m_TargetFps = fps > 0 ? fps : 30;
}

const uint8_t* Engine::GetFrameBuffer() const
{
    return m_Renderer ? m_Renderer->GetFrameBuffer() : nullptr;
}

int32_t Engine::GetScreenWidth() const
{
    return m_Renderer ? m_Renderer->GetScreenWidth() : 0;
}

int32_t Engine::GetScreenHeight() const
{
    return m_Renderer ? m_Renderer->GetScreenHeight() : 0;
}

void Engine::SetScreenDiagonalInches(float inches)
{
    // Not positive, or NaN, is unknown.
    m_ScreenDiagonalInches = inches > 0.0f ? inches : 0.0f;
}

float Engine::GetScreenPixelsPerInch() const
{
    return ScreenPixelsPerInch(GetScreenWidth(), GetScreenHeight(), m_ScreenDiagonalInches);
}

float Engine::GetScreenWidthMeters() const
{
    const float ppi = GetScreenPixelsPerInch();
    return ppi > 0.0f ? static_cast<float>(GetScreenWidth()) / ppi * kMetersPerInch : 0.0f;
}

float Engine::GetScreenHeightMeters() const
{
    const float ppi = GetScreenPixelsPerInch();
    return ppi > 0.0f ? static_cast<float>(GetScreenHeight()) / ppi * kMetersPerInch : 0.0f;
}

ColorFormat Engine::GetFrameBufferFormat() const
{
    return m_Renderer ? m_Renderer->GetColorFormat() : ColorFormat::RGB565;
}

// The package owns the display's lifetime; the engine stores the pointer and
// re-runs the render system's Setup() so it can pick up a DMA buffer the
// display owns, when there is one.
void Engine::SetDisplay(IDisplay* display, const std::string& name)
{
    // If a previous display was registered, shut it down before swapping.
    if (m_Display && m_Display != display)
    {
        m_Display->Shutdown();
    }

    m_Display = display;
    m_DisplayName = name;

    DEKI_LOG_INTERNAL("DekiEngine: display set to '%s'", name.c_str());

    // The framebuffer takes the display's size (and its DMA buffer, where the
    // display offers one of that size). Not only once Initialize has run: the
    // editor hosts the engine without it, and play mode sets a display of the
    // Play view's screen. Skipping this would leave the framebuffer at its old
    // size, and play would refuse to start on any other screen.
    if (m_Renderer && m_Display)
    {
        SizeFramebufferToDisplay();
    }
    // Whatever the new display shows, it is not this framebuffer yet.
    if (m_Renderer)
    {
        m_Renderer->MarkAllDirty();
    }
}

bool Engine::SizeFramebufferToDisplay()
{
    if (!m_Renderer || !m_Display)
    {
        return false;
    }
    int32_t width = 0, height = 0;
    m_Display->GetDisplaySize(&width, &height);
    if (width <= 0 || height <= 0)
    {
        DEKI_LOG_ERROR("Display '%s' reports no size (%dx%d); nothing can be rendered", m_DisplayName.c_str(),
                       (int)width, (int)height);
        return false;
    }
    const ColorFormat format = m_Display->GetColorFormat();
    if (!m_Renderer->Setup(width, height, format))
    {
        DEKI_LOG_ERROR("The %dx%d framebuffer (format %d) for display '%s' needs %u bytes, which could "
                       "not be allocated; nothing will be rendered",
                       (int)width, (int)height, (int)format, m_DisplayName.c_str(),
                       (unsigned)FrameBufferBytes(format, width, height));
        return false;
    }
    m_NoFramebufferLogged = false;
    m_FramesWithoutFramebuffer = 0;
    DEKI_LOG_INTERNAL("DekiEngine: framebuffer %dx%d, format %d, from display '%s'", (int)width, (int)height,
                      (int)format, m_DisplayName.c_str());
    return true;
}

}  // namespace Deki
